const ahora = new Date();
// Fecha/hora en zona horaria Europe/Madrid
const madridDate = new Date(ahora.toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));

const anio = madridDate.getFullYear();
const mes = String(madridDate.getMonth() + 1).padStart(2, '0');
const dia = String(madridDate.getDate()).padStart(2, '0');
const horas = String(madridDate.getHours()).padStart(2, '0');
const minutos = String(madridDate.getMinutes()).padStart(2, '0');

const fecha = `${anio}-${mes}-${dia}`;
const hora = `${horas}:${minutos}`;

const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const diaSemana = diasSemana[madridDate.getDay()];
const mesTexto = meses[madridDate.getMonth()];
const fechaTexto = `${diaSemana} ${madridDate.getDate()} de ${mesTexto} de ${anio}`;

return [{ json: {
  fecha,
  hora,
  diaSemana,
  fechaTexto,
  timestamp: ahora.toISOString()
}}];

const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let args;
if (raw.arguments !== undefined) {
  args = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  args = raw;
}

const servicio = String(args.servicio || '').trim();
const fecha = String(args.fecha || '').trim();
const hora = String(args.hora || '').trim();

const DURACIONES = {
  'Revision': 30, 'Limpieza dental': 45, 'Empaste': 45,
  'Extraccion': 30, 'Blanqueamiento dental': 60,
  'Consulta ortodoncia': 30, 'Consulta implantes': 30, 'Endodoncia': 60
};
const duracion = DURACIONES[servicio] || 30;

const fechaInicio = new Date(`${fecha}T${hora}:00`);
const fechaFin = new Date(fechaInicio.getTime() + duracion * 60000);

const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const diaSemana = fechaInicio.getDay(); // 0=domingo, 1=lunes...

// Horarios: minutos desde medianoche
// 1=lunes, 2=martes, 4=jueves: 9:30-19:00
// 3=miércoles, 5=viernes, 6=sábado: 9:30-14:00
// 0=domingo: cerrado
const HORARIOS = {
  1: { inicio: 9 * 60 + 30, fin: 19 * 60 },
  2: { inicio: 9 * 60 + 30, fin: 19 * 60 },
  3: { inicio: 9 * 60 + 30, fin: 14 * 60 },
  4: { inicio: 9 * 60 + 30, fin: 19 * 60 },
  5: { inicio: 9 * 60 + 30, fin: 14 * 60 },
  6: { inicio: 9 * 60 + 30, fin: 14 * 60 }
};

const horarioDia = HORARIOS[diaSemana];

if (!horarioDia) {
  return [{ json: {
    error: 'dia_cerrado',
    disponible: false,
    mensaje: 'Los domingos la clínica está cerrada. Abrimos de lunes a viernes, y algún sábado al mes.'
  }}];
}

const horaReqMin = fechaInicio.getHours() * 60 + fechaInicio.getMinutes();
const horaFinMin = fechaFin.getHours() * 60 + fechaFin.getMinutes();

if (horaReqMin < horarioDia.inicio) {
  return [{ json: {
    error: 'fuera_horario',
    disponible: false,
    mensaje: 'Esa hora es antes de que abramos. Empezamos a atender a las nueve y media.'
  }}];
}

if (horaFinMin > horarioDia.fin) {
  const esMediodia = horarioDia.fin === 14 * 60;
  const nombreDia = diasSemana[diaSemana];
  return [{ json: {
    error: 'fuera_horario',
    disponible: false,
    mensaje: `Esa hora no nos da tiempo antes del cierre. Los ${nombreDia} cerramos a las ${esMediodia ? 'dos de la tarde' : 'siete de la tarde'}.`
  }}];
}

return [{ json: {
  servicio, fecha, hora, duracion,
  fechaInicio: fechaInicio.toISOString(),
  fechaFin: fechaFin.toISOString(),
  fechaTexto: `${diasSemana[diaSemana]} ${fechaInicio.getDate()} de ${meses[fechaInicio.getMonth()]}`
}}];

const input = $('Parsear Argumentos').first().json;
const eventos = $('Google Calendar - Consultar Hueco').all();

const HORARIOS = {
  1: { inicio: 9 * 60 + 30, fin: 19 * 60 },
  2: { inicio: 9 * 60 + 30, fin: 19 * 60 },
  3: { inicio: 9 * 60 + 30, fin: 14 * 60 },
  4: { inicio: 9 * 60 + 30, fin: 19 * 60 },
  5: { inicio: 9 * 60 + 30, fin: 14 * 60 },
  6: { inicio: 9 * 60 + 30, fin: 14 * 60 }
};

const newStart = new Date(input.fechaInicio);
const newEnd = new Date(input.fechaFin);
const ahora = new Date();
const durMin = input.duracion || 30;

const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];

function siguienteHueco(desde, eventos) {
  let candidato = new Date(desde);
  candidato.setSeconds(0, 0);
  // Redondear al próximo slot de 30 min
  const min = candidato.getMinutes();
  const resto = min % 30;
  if (resto !== 0) candidato.setMinutes(min + (30 - resto));

  for (let i = 0; i < 336; i++) {
    const dia = candidato.getDay();
    const h = HORARIOS[dia];
    if (h) {
      const minCand = candidato.getHours() * 60 + candidato.getMinutes();
      const minFin = minCand + durMin;
      if (minCand >= h.inicio && minFin <= h.fin) {
        const candEnd = new Date(candidato.getTime() + durMin * 60000);
        const conflicto = eventos.some(ev => {
          const evStart = new Date(ev.start.dateTime || ev.start.date + 'T00:00:00');
          const evEnd = new Date(ev.end.dateTime || ev.end.date + 'T00:00:00');
          return candidato < evEnd && candEnd > evStart;
        });
        if (!conflicto) return candidato;
      }
    }
    candidato = new Date(candidato.getTime() + 30 * 60000);
  }
  return null;
}

if (newStart <= ahora) {
  const eventosActivos = eventos.map(e => e.json).filter(e => e.status !== 'cancelled' && (e.start?.dateTime || e.start?.date));
  const sig = siguienteHueco(new Date(ahora.getTime() + 30 * 60000), eventosActivos);
  if (sig) {
    const sigFecha = sig.toISOString().split('T')[0];
    const sigHora = `${String(sig.getHours()).padStart(2,'0')}:${String(sig.getMinutes()).padStart(2,'0')}`;
    const sigTexto = `${diasSemana[sig.getDay()]} ${sig.getDate()} de ${meses[sig.getMonth()]}`;
    return [{ json: { disponible: false, mensaje: `Esa hora ya ha pasado. El siguiente hueco disponible sería el ${sigTexto} a las ${sigHora}`, siguiente_disponible: { fecha: sigFecha, hora: sigHora } }}];
  }
  return [{ json: { disponible: false, mensaje: 'Esa hora ya ha pasado. Dinos qué día y hora le viene bien y lo comprobamos.' }}];
}

const eventosActivos = eventos
  .map(e => e.json)
  .filter(e => e.status !== 'cancelled' && (e.start?.dateTime || e.start?.date));

const hayConflicto = eventosActivos.some(ev => {
  const evStart = new Date(ev.start.dateTime || ev.start.date + 'T00:00:00');
  const evEnd = new Date(ev.end.dateTime || ev.end.date + 'T00:00:00');
  return newStart < evEnd && newEnd > evStart;
});

if (!hayConflicto) {
  return [{ json: {
    disponible: true,
    fecha: input.fecha,
    hora: input.hora,
    servicio: input.servicio,
    mensaje: `Hay disponibilidad el ${input.fechaTexto} a las ${input.hora}`
  }}];
}

const sig = siguienteHueco(new Date(newStart.getTime() + 30 * 60000), eventosActivos);
if (sig) {
  const sigFecha = sig.toISOString().split('T')[0];
  const sigHora = `${String(sig.getHours()).padStart(2,'0')}:${String(sig.getMinutes()).padStart(2,'0')}`;
  const sigTexto = `${diasSemana[sig.getDay()]} ${sig.getDate()} de ${meses[sig.getMonth()]}`;
  return [{ json: { disponible: false, mensaje: `No hay disponibilidad a esa hora. El siguiente hueco libre es el ${sigTexto} a las ${sigHora}`, siguiente_disponible: { fecha: sigFecha, hora: sigHora } }}];
}

return [{ json: { disponible: false, mensaje: 'No hay disponibilidad próxima. Dinos qué días y horarios le vienen mejor y lo buscamos.' }}];

const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let body;
if (raw.arguments !== undefined) {
  body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
